def install_this_file():
    if os.name != "nt":
        raise SystemExit("--install sólo funciona en Windows.")

    script = str(Path(__file__).resolve())
    python = str(Path(sys.executable).resolve())
    action = f'"{python}" "{script}"'

    p = subprocess.run(
        [
            "schtasks", "/Create",
            "/TN", TASK_NAME,
            "/TR", action,
            "/SC", "DAILY",
            "/ST", "18:30",
            "/F",
        ],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )

    if p.returncode != 0:
        print(p.stdout)
        print(p.stderr)
        raise SystemExit("No se pudo instalar la tarea.")

    print(p.stdout.strip())
    print("Instalado: este mismo archivo v1.11 se ejecutará a las 18:30.")

def uninstall_this_file():
    if os.name != "nt":
        raise SystemExit("--uninstall sólo funciona en Windows.")

    p = subprocess.run(
        ["schtasks", "/Delete", "/TN", TASK_NAME, "/F"],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    print((p.stdout or p.stderr).strip())

# ---------------------------------------------------------------------
# MARKET DATA
# ---------------------------------------------------------------------

def extract_ticker(raw, ticker):
    if isinstance(raw.columns, pd.MultiIndex):
        l0 = raw.columns.get_level_values(0)
        l1 = raw.columns.get_level_values(1)
        if ticker in l0:
            d = raw[ticker].copy()
        elif ticker in l1:
            d = raw.xs(ticker, axis=1, level=1).copy()
        else:
            return None
    else:
        d = raw.copy()

    d.index = pd.to_datetime(d.index).tz_localize(None)
    d.columns = [str(c).title() for c in d.columns]
    return d.sort_index()

def download_history():
    tickers = TARGETS + PREDICTORS
    print("\n[Signal Lab] Descargando historia...")
    raw = yf.download(
        tickers,
        start=START,
        auto_adjust=True,
        progress=False,
        threads=True,
        group_by="column",
    )

    out = {}
    for t in tickers:
        d = extract_ticker(raw, t)
        if d is None or "Close" not in d:
            continue
        s = pd.to_numeric(d["Close"], errors="coerce").dropna()
        if len(s):
            out[t] = s

    for t in TARGETS + ["CLP=X"]:
        if t not in out:
            raise RuntimeError(f"Falta serie esencial: {t}")

    return out

# ---------------------------------------------------------------------
# FEATURES
# ---------------------------------------------------------------------

def rsi(s, n=14):
    d = s.diff()
    up = d.clip(lower=0).rolling(n).mean()
    dn = (-d.clip(upper=0)).rolling(n).mean()
    rs = up / dn.replace(0, np.nan)
    return 100 - 100 / (1 + rs)

def price_block(s, prefix):
    x = pd.DataFrame(index=s.index)
    dr = s.pct_change(fill_method=None)

    for n in [1, 2, 5, 10, 20, 60, 120]:
        x[f"{prefix}_ret{n}"] = s.pct_change(n, fill_method=None)

    for n in [5, 20, 60]:
        x[f"{prefix}_vol{n}"] = dr.rolling(n).std() * np.sqrt(252)

    for n in [20, 60, 200]:
        x[f"{prefix}_sma{n}"] = s / s.rolling(n).mean() - 1

    x[f"{prefix}_rsi14"] = rsi(s, 14) / 100.0
    x[f"{prefix}_dd60"] = s / s.rolling(60).max() - 1
    x[f"{prefix}_dd252"] = s / s.rolling(252).max() - 1
    return x

def level_block(s, prefix):
    x = pd.DataFrame(index=s.index)
    x[f"{prefix}_level"] = s
    for n in [1, 5, 20]:
        x[f"{prefix}_diff{n}"] = s.diff(n)
    mean20 = s.rolling(20).mean()
    std20 = s.rolling(20).std()
    x[f"{prefix}_z20"] = (s - mean20) / std20.replace(0, np.nan)
    return x

def safe_name(t):
    return (
        t.replace("^", "")
        .replace("=", "_")
        .replace("-", "_")
        .replace(".", "_")
        .lower()
    )

def build_frame(asset, market):
    usd = market[asset]
    fx = market["CLP=X"].reindex(usd.index).ffill(limit=5)
    clp = usd * fx
    idx = clp.index

    blocks = [
        price_block(clp, "self"),
        price_block(usd, "usd_asset"),
        price_block(fx, "usdclp"),
    ]

    predictor_returns = {}

    for t in PREDICTORS:
        if t == "CLP=X" or t not in market:
            continue

        s = market[t].reindex(idx).ffill(limit=5)
        name = safe_name(t)

        if t == "^VIX":
            blocks.append(level_block(s, name))
        else:
            blocks.append(price_block(s, name))

        predictor_returns[name] = s.pct_change(fill_method=None)

    X = pd.concat(blocks, axis=1)

    own_dr = clp.pct_change(fill_method=None)

    # Correlaciones móviles: relación de cada predictor con el activo.
    for name, pr in predictor_returns.items():
        for n in [20, 60]:
            X[f"corr_self_{name}_{n}"] = own_dr.rolling(n).corr(pr)

    # Spreads / señales relativas.
    def col(name, suffix):
        c = f"{name}_{suffix}"
        return X[c] if c in X else pd.Series(np.nan, index=X.index)

    X["spread_eem_spy_20"] = col("eem", "ret20") - col("spy", "ret20")
    X["spread_fxi_eem_20"] = col("fxi", "ret20") - col("eem", "ret20")
    X["spread_hg_gc_20"] = col("hg_f", "ret20") - col("gc_f", "ret20")
    X["spread_uup_tlt_20"] = col("uup", "ret20") - col("tlt", "ret20")
    X["spread_self_spy_20"] = X["self_ret20"] - col("spy", "ret20")

    # Interacciones económicas simples.
    if "vix_level" in X:
        X["risk_momentum_interaction"] = (
            X["self_ret20"] * X["vix_level"]
        )

    if "hg_f_ret20" in X:
        X["copper_usd_interaction"] = (
            X["hg_f_ret20"] - X["usdclp_ret20"]
        )

    X["price_clp"] = clp
    X["daily_ret_clp"] = clp.pct_change(fill_method=None)

    # Señal t -> ejecución cierre t+1 -> salida h sesiones después.
    for h in HORIZONS:
        entry = clp.shift(-1)
        exit_ = clp.shift(-(h + 1))
        fwd = exit_ / entry - 1
        X[f"fwd_ret_{h}"] = fwd
        X[f"y_up_{h}"] = np.where(
            fwd.notna(),
            (fwd > 0).astype(float),
            np.nan,
        )

    return X

def feature_cols(df):
    exclude = {"price_clp", "daily_ret_clp"}
    for h in HORIZONS:
        exclude |= {f"fwd_ret_{h}", f"y_up_{h}"}
    return [c for c in df.columns if c not in exclude]

# ---------------------------------------------------------------------
# PERFORMANCE
# ---------------------------------------------------------------------

def perf(ret):
    r = pd.Series(ret).fillna(0.0)
    curve = (1 + r).cumprod()
    if len(curve) == 0:
        return {
            "total_return": 0.0,
            "sharpe": 0.0,
            "max_drawdown": 0.0,
            "turnover": 0.0,
        }

    total = float(curve.iloc[-1] - 1)
    vol = float(r.std() * np.sqrt(252))
    sharpe = float(r.mean() * 252 / vol) if vol > 1e-12 else 0.0
    dd = curve / curve.cummax() - 1

    return {
        "total_return": total,
        "sharpe": sharpe,
        "max_drawdown": float(dd.min()),
    }

def weeklyize(pos):
    out = pd.Series(index=pos.index, dtype=float)
    state = 0.0
    for i, (dt, v) in enumerate(pos.fillna(0.0).items()):
        if i == 0 or i % 5 == 0:
            state = float(np.clip(v, 0, 1))
        out.loc[dt] = state
    return out

def strategy_returns(position, daily_ret):
    target = weeklyize(position)
    exec_pos = target.shift(1).fillna(0.0)
    held = target.shift(2).fillna(0.0)
    turnover = exec_pos.diff().abs().fillna(exec_pos.abs())
    gross = held * daily_ret.fillna(0.0)
    net = gross - turnover * ONE_WAY_COST
    return net, held, turnover

# ---------------------------------------------------------------------
# STRICT TEMPORAL SPLITS
# ---------------------------------------------------------------------

def known_before_year(df, year, h):
    idx = df.index[df.index.year == year]
    if len(idx) == 0:
        return pd.DataFrame()

    first_pos = df.index.get_loc(idx[0])
    end = first_pos - (h + 1)
    if end <= 0:
        return pd.DataFrame()

    return df.iloc[:end].dropna(
        subset=[f"fwd_ret_{h}", f"y_up_{h}"]
    )

def select_stable_features(
    df,
    h,
    selection_years,
    max_features=24,
):
    feats = feature_cols(df)
    stats = []

    for f in feats:
        ics = []

        for y in selection_years:
            z = df[df.index.year == y][[f, f"fwd_ret_{h}"]].dropna()
            if len(z) < 80:
                continue

            # Spearman sin scipy: correlación de ranks.
            ic = z[f].rank().corr(z[f"fwd_ret_{h}"].rank())
            if pd.notna(ic):
                ics.append(float(ic))

        if len(ics) < max(1, len(selection_years) - 1):
            continue

        mean_ic = float(np.mean(ics))
        signs = [np.sign(x) for x in ics if x != 0]
        if not signs:
            consistency = 0.0
        else:
            dominant = np.sign(mean_ic)
            consistency = float(
                np.mean([s == dominant for s in signs])
            )

        stats.append({
            "feature": f,
            "mean_ic": mean_ic,
            "abs_mean_ic": abs(mean_ic),
            "consistency": consistency,
            "folds": len(ics),
        })

    st = pd.DataFrame(stats)
    if st.empty:
        return [], st

    eligible = st[
        (st["consistency"] >= 0.50)
        & (st["abs_mean_ic"] >= 0.01)
    ].copy()

    if eligible.empty:
        eligible = st.nlargest(
            min(max_features, len(st)),
            "abs_mean_ic",
        )
    else:
        eligible = eligible.sort_values(
            ["consistency", "abs_mean_ic"],
            ascending=False,
        ).head(max_features)

    return eligible["feature"].tolist(), eligible

# ---------------------------------------------------------------------
# MODELS
# ---------------------------------------------------------------------

def logit_model():
    return Pipeline([
        ("imp", SimpleImputer(strategy="median")),
        ("sc", StandardScaler()),
        ("m", LogisticRegression(
            C=0.20,
            max_iter=1500,
            class_weight="balanced",
            random_state=RANDOM_STATE,
        )),
    ])

def hgb_model():
    return Pipeline([
        ("imp", SimpleImputer(strategy="median")),
        ("m", HistGradientBoostingClassifier(
            max_iter=120,
            learning_rate=0.04,
            max_leaf_nodes=10,
            min_samples_leaf=24,
            l2_regularization=4.0,
            random_state=RANDOM_STATE,
        )),
    ])

def ridge_model():
    return Pipeline([
        ("imp", SimpleImputer(strategy="median")),
        ("sc", StandardScaler()),
        ("m", Ridge(alpha=25.0)),
    ])

def vote_signal(train, pred, features, stats):
    if not features:
        return pd.Series(0.0, index=pred.index)

    signs = {}
    if stats is not None and len(stats):
        signs = {
            r.feature: np.sign(float(r.mean_ic))
            for r in stats.itertuples()
        }

    vals = []
    for f in features:
        mu = train[f].mean()
        sd = train[f].std()

        if not np.isfinite(sd) or sd <= 1e-12:
            continue

        z = (pred[f] - mu) / sd
        sign = signs.get(f, 1.0)
        vals.append((z * sign).clip(-4, 4))

    if not vals:
        return pd.Series(0.0, index=pred.index)

    score = pd.concat(vals, axis=1).mean(axis=1)
    return np.tanh(score / 2.0)

def model_alphas(train, pred, h, features, stats):
    Xtr = train[features]
    Xp = pred[features]
    y = train[f"y_up_{h}"].astype(int)

    out = {}

    if y.nunique() >= 2:
        lg = logit_model()
        lg.fit(Xtr, y)
        out["LOGIT"] = pd.Series(
            2 * lg.predict_proba(Xp)[:, 1] - 1,
            index=pred.index,
        )

        hg = hgb_model()
        hg.fit(Xtr, y)
        out["HGB"] = pd.Series(
            2 * hg.predict_proba(Xp)[:, 1] - 1,
            index=pred.index,
        )

    rr = ridge_model()
    rr.fit(Xtr, train[f"fwd_ret_{h}"])

    pred_ret = pd.Series(
        rr.predict(Xp),
        index=pred.index,
    )

    scale = float(train[f"fwd_ret_{h}"].std())
    if not np.isfinite(scale) or scale <= 1e-6:
        scale = 0.01

    out["RIDGE"] = np.tanh(pred_ret / scale)
    out["STABLE_VOTE"] = vote_signal(
        train, pred, features, stats
    )

    return out

def alpha_to_position(alpha):
    # Long-only: sólo se expone con evidencia positiva.
    return ((alpha - 0.03) / 0.20).clip(0, 1)

def score_model_alpha(alpha, daily_ret):
    pos = alpha_to_position(alpha)
    net, held, turnover = strategy_returns(pos, daily_ret)
    p = perf(net)

    score = (
        p["sharpe"]
        + 0.30 * p["total_return"]
        - 0.55 * abs(p["max_drawdown"])
        - 0.015 * float(turnover.sum())
    )

    return score, p, float(turnover.sum())

def learn_model_weights(alphas, validation):
    rows = []

    for name, a in alphas.items():
        score, p, turnover = score_model_alpha(
            a,
            validation["daily_ret_clp"],
        )

        rows.append({
            "model": name,
            "score": score,
            "val_return": p["total_return"],
            "val_sharpe": p["sharpe"],
            "val_drawdown": p["max_drawdown"],
            "val_turnover": turnover,
        })

    table = pd.DataFrame(rows)
    if table.empty:
        return {}, table

    # Sólo modelos con score positivo reciben peso.
    positive = table[table["score"] > 0].copy()

    if positive.empty:
        return {}, table

    # Penalización por dependencia entre señales.
    names = positive["model"].tolist()
    A = pd.concat(
        [alphas[n].rename(n) for n in names],
        axis=1,
    ).corr().abs()

    adjusted = []
    for r in positive.itertuples():
        others = [
            x for x in names
            if x != r.model
        ]
        dep = (
            float(A.loc[r.model, others].mean())
            if others else 0.0
        )
        adjusted.append(
            max(0.0, float(r.score)) / (1.0 + dep)
        )

    adjusted = np.array(adjusted)
    if adjusted.sum() <= 0:
        return {}, table

    weights = adjusted / adjusted.sum()

    return dict(zip(names, weights)), table

def ensemble_alpha(alphas, weights):
    if not weights:
        if alphas:
            return pd.Series(
                0.0,
                index=next(iter(alphas.values())).index,
            )
        return pd.Series(dtype=float)

    out = None
    for name, w in weights.items():
        a = alphas[name] * w
        out = a if out is None else out + a
    return out

# ---------------------------------------------------------------------
# ONE HORIZON CANDIDATE
# ---------------------------------------------------------------------

def horizon_candidate(df, test_year, h):
    selection_years = [
        test_year - 3,
        test_year - 2,
    ]
    val_year = test_year - 1

    if not all(np.any(df.index.year == y) for y in selection_years + [val_year]):
        return None

    features, feat_stats = select_stable_features(
        df, h, selection_years
    )

    if len(features) < 3:
        return None

    val = df[df.index.year == val_year].copy()
    train_val = known_before_year(df, val_year, h)

    if len(train_val) < 400 or val.empty:
        return None

    alphas_val = model_alphas(
        train_val,
        val,
        h,
        features,
        feat_stats,
    )

    weights, weight_table = learn_model_weights(
        alphas_val,
        val,
    )

    if not weights:
        return {
            "horizon": h,
            "features": features,
            "feature_stats": feat_stats,
            "weights": {},
            "weight_table": weight_table,
            "validation_score": -999.0,
        }

    ens_val = ensemble_alpha(
        alphas_val,
        weights,
    )

    val_score, val_perf, val_turnover = score_model_alpha(
        ens_val,
        val["daily_ret_clp"],
    )

    return {
        "horizon": h,
        "features": features,
        "feature_stats": feat_stats,
        "weights": weights,
        "weight_table": weight_table,
        "validation_score": val_score,
        "validation_return": val_perf["total_return"],
        "validation_sharpe": val_perf["sharpe"],
        "validation_drawdown": val_perf["max_drawdown"],
        "validation_turnover": val_turnover,
    }

# ---------------------------------------------------------------------
# WALK FORWARD ASSET
# ---------------------------------------------------------------------

def run_asset(asset, df):
    yearly = []
    signal_rows = []
    weight_rows = []
    daily_rows = []

    latest_year = int(df.index.max().year)

    for test_year in range(FIRST_TEST_YEAR, latest_year + 1):
        if not np.any(df.index.year == test_year):
            continue

        candidates = []

        for h in HORIZONS:
            c = horizon_candidate(df, test_year, h)
            if c is not None:
                candidates.append(c)

        if not candidates:
            continue

        # Horizonte elegido exclusivamente por validación del año anterior.
        best = max(
            candidates,
            key=lambda x: x["validation_score"],
        )

        h = best["horizon"]
        test = df[df.index.year == test_year].copy()
        train_final = known_before_year(
            df, test_year, h
        )

        if len(train_final) < 500 or test.empty:
            continue

        if not best["weights"]:
            ens_test = pd.Series(0.0, index=test.index)
        else:
            alphas_test = model_alphas(
                train_final,
                test,
                h,
                best["features"],
                best["feature_stats"],
            )
            ens_test = ensemble_alpha(
                alphas_test,
                best["weights"],
            )

        pos = alpha_to_position(ens_test)
        net, held, turnover = strategy_returns(
            pos,
            test["daily_ret_clp"],
        )
        p = perf(net)

        yearly.append({
            "asset": asset,
            "test_year": test_year,
            "chosen_horizon": h,
            "validation_score": best["validation_score"],
            "validation_return": best.get("validation_return", np.nan),
            "validation_sharpe": best.get("validation_sharpe", np.nan),
            "test_return": p["total_return"],
            "test_sharpe": p["sharpe"],
            "test_drawdown": p["max_drawdown"],
            "test_turnover": float(turnover.sum()),
            "mean_position": float(held.mean()),
            "n_features": len(best["features"]),
        })

        for r in best["feature_stats"].itertuples():
            signal_rows.append({
                "asset": asset,
                "test_year": test_year,
                "horizon": h,
                "feature": r.feature,
                "mean_ic": r.mean_ic,
                "consistency": r.consistency,
            })

        for name, w in best["weights"].items():
            weight_rows.append({
                "asset": asset,
                "test_year": test_year,
                "horizon": h,
                "model": name,
                "weight": w,
            })

        z = pd.DataFrame(index=test.index)
        z["asset"] = asset
        z["year"] = test_year
        z["alpha"] = ens_test
        z["position"] = held
        z["turnover"] = turnover
        z["strategy_ret"] = net
        z["daily_ret_clp"] = test["daily_ret_clp"]
        daily_rows.append(z)

        print(
            f"  {asset} {test_year}: H={h} | "
            f"val={best['validation_score']:.2f} | "
            f"futuro={p['total_return']:+.2%} | "
            f"Sharpe={p['sharpe']:.2f} | "
            f"features={len(best['features'])}"
        )

    return (
        pd.DataFrame(yearly),
        pd.DataFrame(signal_rows),
        pd.DataFrame(weight_rows),
        pd.concat(daily_rows).sort_index()
        if daily_rows else pd.DataFrame(),
    )

# ---------------------------------------------------------------------
# PORTFOLIO / METRICS
# ---------------------------------------------------------------------

def build_portfolio(daily, frames):
    idx = pd.DatetimeIndex(sorted(daily.index.unique()))
    strategy = pd.Series(0.0, index=idx)
    benchmark = pd.Series(0.0, index=idx)

    for asset in TARGETS:
        z = daily[daily["asset"] == asset]
        sr = (
            z["strategy_ret"]
            .groupby(z.index).last()
            .reindex(idx).fillna(0)
        )
        strategy += MAX_ASSET_WEIGHT * sr

        benchmark += (
            MAX_ASSET_WEIGHT
            * frames[asset]["daily_ret_clp"]
            .reindex(idx).fillna(0)
        )

    out = pd.DataFrame(index=idx)
    out["strategy_ret"] = strategy
    out["benchmark_ret"] = benchmark
    out["capital_strategy"] = (
        INITIAL_CAPITAL * (1 + strategy).cumprod()
    )
    out["capital_benchmark"] = (
        INITIAL_CAPITAL * (1 + benchmark).cumprod()
    )
    return out

def metrics_table(port):
    s = perf(port["strategy_ret"])
    b = perf(port["benchmark_ret"])

    return pd.DataFrame([
        {"name": "SIGNAL_DISCOVERY_CHALLENGER", **s},
        {"name": "BENCHMARK_30_30_30_CLP", **b},
    ])

# ---------------------------------------------------------------------
# CURRENT DISCOVERY SIGNAL
# ---------------------------------------------------------------------

def current_from_yearly(yearly, weights, signals, frames):
    rows = []

    if yearly.empty:
        return pd.DataFrame()

    latest_year = int(yearly["test_year"].max())

    for asset in TARGETS:
        y = yearly[
            (yearly["asset"] == asset)
            & (yearly["test_year"] == latest_year)
        ]

        if y.empty:
            continue

        row = y.iloc[-1]
        h = int(row["chosen_horizon"])

        w = weights[
            (weights["asset"] == asset)
            & (weights["test_year"] == latest_year)
            & (weights["horizon"] == h)
        ]

        top_signals = signals[
            (signals["asset"] == asset)
            & (signals["test_year"] == latest_year)
            & (signals["horizon"] == h)
        ].copy()

        top_signals["abs_ic"] = top_signals["mean_ic"].abs()
        top_signals = top_signals.nlargest(8, "abs_ic")

        rows.append({
            "asset": asset,
            "research_year": latest_year,
            "chosen_horizon": h,
            "validation_score": row["validation_score"],
            "historical_test_return": row["test_return"],
            "models": " + ".join(
                f"{r.model}:{r.weight:.2f}"
                for r in w.itertuples()
            ),
            "top_historical_signals": " | ".join(
                f"{r.feature}({r.mean_ic:+.3f})"
                for r in top_signals.itertuples()
            ),
        })

    return pd.DataFrame(rows)

# ---------------------------------------------------------------------
# RESEARCH CADENCE
# ---------------------------------------------------------------------

def research_due(force=False):
    if force or not STATE_JSON.exists():
        return True

    try:
        state = json.loads(
            STATE_JSON.read_text(encoding="utf-8")
        )
        last = pd.Timestamp(state["last_completed_utc"])
        now = pd.Timestamp.now(tz="UTC")

        if last.tzinfo is None:
            last = last.tz_localize("UTC")
        else:
            last = last.tz_convert("UTC")

        return (now - last).days >= RESEARCH_EVERY_DAYS

    except Exception:
        return True

def save_research_state():
    STATE_JSON.write_text(
        json.dumps(
            {
                "last_completed_utc":
                    datetime.now(timezone.utc).isoformat(timespec="seconds"),
                "version": "v1.11",
            },
            indent=2,
        ),
        encoding="utf-8",
    )

# ---------------------------------------------------------------------
# SIGNAL LAB
# ---------------------------------------------------------------------

def run_signal_lab():
    market = download_history()
    frames = {}

    for asset in TARGETS:
        print(f"[Signal Lab] Construyendo {asset}...")
        frames[asset] = build_frame(asset, market)

    ys = []
    ss = []
    ws = []
    ds = []

    print("\n[Signal Lab] Walk-forward estricto...")

    for asset in TARGETS:
        y, s, w, d = run_asset(
            asset, frames[asset]
        )

        if len(y):
            ys.append(y)
        if len(s):
            ss.append(s)
        if len(w):
            ws.append(w)
        if len(d):
            ds.append(d)

    yearly = pd.concat(ys, ignore_index=True)
    signals = pd.concat(ss, ignore_index=True)
    weights = pd.concat(ws, ignore_index=True)
    daily = pd.concat(ds).sort_index()

    port = build_portfolio(daily, frames)
    metrics = metrics_table(port)

    current = current_from_yearly(
        yearly, weights, signals, frames
    )

    yearly.to_csv(
        SUMMARY_CSV, index=False,
        encoding="utf-8-sig"
    )
    signals.to_csv(
        SIGNALS_CSV, index=False,
        encoding="utf-8-sig"
    )
    weights.to_csv(
        WEIGHTS_CSV, index=False,
        encoding="utf-8-sig"
    )
    port.to_csv(
        PORTFOLIO_CSV,
        encoding="utf-8-sig"
    )
    metrics.to_csv(
        METRICS_CSV,
        index=False,
        encoding="utf-8-sig"
    )
    current.to_csv(
        CURRENT_CSV,
        index=False,
        encoding="utf-8-sig"
    )

    save_research_state()

    print("\n" + "=" * 92)
    print("SIGNAL DISCOVERY LAB — RESULTADO")
    print("=" * 92)

    with pd.option_context(
        "display.max_columns", None,
        "display.width", 180,
    ):
        print(metrics)

    print(
        "\nCapital Signal Challenger:",
        f"${port['capital_strategy'].iloc[-1]:,.0f}"
    )
    print(
        "Capital Benchmark:",
        f"${port['capital_benchmark'].iloc[-1]:,.0f}"
    )

    print("\nSeñales históricas actuales:")
    with pd.option_context(
        "display.max_columns", None,
        "display.width", 200,
    ):
        print(current)

    return metrics

# ---------------------------------------------------------------------
# MAIN
# ---------------------------------------------------------------------

def main():
    p = argparse.ArgumentParser()
    p.add_argument("--research", action="store_true")
    p.add_argument("--install", action="store_true")
    p.add_argument("--uninstall", action="store_true")
    p.add_argument("--status", action="store_true")
    p.add_argument("--full", action="store_true")
    args = p.parse_args()

    if args.install:
        install_this_file()
        return

    if args.uninstall:
        uninstall_this_file()
        return

    if args.status:
        print("\nMFP-3 v1.11 STATUS")
        print("Signal Lab:", LAB.resolve())
        print("Research due:", research_due(False))
        print("Summary exists:", SUMMARY_CSV.exists())
        print("Current signals:", CURRENT_CSV.exists())
        return

    print("\n" + "=" * 94)
    print("MFP-3 ONE FILE v1.11 — HISTORICAL SIGNAL DISCOVERY")
    print("=" * 94)

    # Daily system: Champion + events + causal engine.
    run_base(args)

    # Heavy lab only weekly or forced.
    if research_due(args.research):
        print(
            "\n[v1.11] Ejecutando laboratorio histórico. "
            "Puede tardar varios minutos..."
        )
        run_signal_lab()
    else:
        print(
            "\n[v1.11] Signal Lab no necesita repetirse hoy. "
            "Se ejecuta automáticamente cada 7 días."
        )

    print(
        "\nLa retroalimentación histórica permanece en el Challenger. "
        "v1.7-FROZEN sigue intacta."
    )

if __name__ == "__main__":
    main()
